    const items = (cc.items as Array<{ name: string }>) ?? [];
    const CREAM  = "#FFF8F1";
    const ACCENT = "#E0BE9A";
    const DARK   = "#1F1F1F";
    const MUTED  = "#5B4D43";
    const FONT   = "'Fahkwang', serif";
